{\sc[Ear Decomposition Theorem]}\\
    A bipartite graph is matching covered if and only if it admits an ear decomposition.
    \label{thm : odd ear decomp}

{\sc[Main Theorem: Characterization of $\mathcal{H}_2$]}\\
    A graph is a $2$-vertex extremal{} minimal bipartite matching covered graph{} if and only if it is obtained from a Halin tree{} by isomorphic leaf matching{}.
    \label{thm : evm}

{\sc[Characterization of $\mathcal{H}_3$]}\\
    A graph is a $2$-vertex $n$-extremal{} minimal bipartite matching covered graph{} if and only if it is obtained from a cubic Halin tree{} by isomorphic leaf matching{}.
    \label{thm : evn}

{\sc[Characterization of $\mathcal{H}_4$]}\\
    A graph is an edge extremal{} minimal bipartite matching covered graph{} if and only if it is obtained from a star by isomorphic leaf matching{}.
    \label{thm : ee}

Any graph $G$ obtained from a Halin tree{} $T$ by isomorphic leaf matching{} is a minimal bipartite matching covered graph{} that is $2$-vertex extremal{}. Furthermore:
    \begin{enumerate}

        \item if $T$ is a cubic Halin tree{} then $G$ is also $2$-vertex $n$-extremal{}, whereas
        \item if $T$ is a star then $G$ is also edge extremal{}. 
    \end{enumerate}
    \label{thm : embmcg TcupT'}

{\sc[Characterization of $\mathcal{H}_0$]}\\
    A graph $G$, distinct from $C_4$, is a $2$-edge extremal{} minimal bipartite matching covered graph{} if and only if its partial retract{} $\widehat{G}$ is a $2$-vertex extremal{} minimal bipartite matching covered graph{}.
    \label{thm : eem}

{\sc[Characterization of $\mathcal{H}_1$]}\\
    A graph $G$ is a $2$-edge $n$-extremal{} minimal bipartite matching covered graph{} if and only if its partial retract{} $\widehat{G}$ is an edge extremal{} minimal bipartite matching covered graph{} and $\Delta(G)=3$.
    \label{thm : een}

Every extremal minimal bipartite matching covered graph{}, distinct from $C_4$, satisfies the following:
    \begin{enumerate}
        \item $E_2$ is a perfect matching of $G[V_2]$ and $|E_2|=m-n+2$,
        \item each ear in any ear decomposition has exactly one $2$-edge, and
        \item each conformal cycle has precisely two $2$-edges.



    \end{enumerate}

    \label{lem : basic prop of embmcg}

Every extremal minimal bipartite matching covered graph{}, distinct from $C_4$, satisfies the following:
    \begin{enumerate}



        \item $|V_3|=3n-2m-4$,
        \item $|E_{3,2}|=2m-2n+4$, and 
        \item $|E_{3}|=3n-2m-6=|V_3|-2$.\hfill{$\qed$}        
    \end{enumerate}

    \label{cor : counting prop of embmcg}

{\sc[Balanced $2$-cut Property]}\\
    In an extremal minimal bipartite matching covered graph{}, each \mbox{$3$-edge}{} participates in a balanced $2$-cut with some other \mbox{$3$-edge}{}.
    \label{thm : 2-cut property}

Let $G[A,B]$ denote an extremal minimal bipartite matching covered graph{} and let $e:=ab$ denote any \mbox{$3$-edge}{} so that $a\in A$. We intend to show the existence of another \mbox{$3$-edge}{}, say $f$, such that $\{e,f\}$ is a balanced $2$-cut.

    By Proposition~\ref{prop : C_u}, there is a conformal cycle $C$ such that $a\in C$ and $e\notin C$. Now, let $H$ be a maximal conformal matching covered subgraph of $G$ such that $a\in H$ and $e\notin H$. By Lemma~\ref{lem : cmcs is induced}, $H$ is induced; thus $b\notin H$. In particular, $e\in \partial^A(H)$. We shall demonstrate that $\partial(H)$ is the desired balanced $2$-cut. In order to do so, we state and prove specific claims; within their proofs, we shall invoke ear decomposition results (namely, Lemma~\ref{lem : P_e} and Theorem~\ref{thm : strong ear decomp}) several times without mentioning it explicitly.

    \begin{stat}
    $\partial^A(H)=\{e\}$.
    \end{stat}

    \begin{proof}
    Suppose not; then there is an edge $f\neq e$ in $\partial^A(H)$. Now, there is an ear $P_f$ of $H$ containing $f$. Observe that $e\notin P_f$ since $P_f$ is odd. Thus, $H':=H\cup P_f$ is a larger conformal matching covered subgraph of $G$ such that $a\in H'$ and $e\notin H'$; this contradicts the maximality of $H$. This proves that $\partial^A(H)=\{e\}$. 
    \end{proof}

    In the proofs of the next two claims, every instance of $2$-edge refers to the condition of being a $2$-edge in the graph $G$ similar to our earlier discussion (after the proof of Lemma~\ref{lem : 2-edge in ear}).
    \begin{stat}
    $|\partial^B(H)|= 1$.
    \label{stat : one bw edge}
    \end{stat}
    \begin{proof}
    Since $G$ is \mbox{$2$-connected}, $|\partial^B(H)|\geqslant1$. Now suppose that $f_1$ and $f_2$ are distinct edges in $\partial^B(H)$ and let $b_1$ and $b_2$ denote their (not necessarily distinct) ends in $H$, respectively. Now, there is an ear $P'$ of $H$ containing $f_1$ (which must also contain $e$). Furthermore, there is an ear $P_2$ of $H\cup P'$ containing $f_2$. Let $x\in A$ be the end of $P_2$ distinct from $b_2$ (see Figure~\ref{subfig: h cup p+p1 cup p2}). Observe that $x\notin H$ since $\partial^A(H)=\{e\}$ and $e\in P'$. Thus, $x$ is an internal vertex of $P'$. Consequently, $x$ splits $P'$ into two paths, say $P:=aP'x$ and $P_1:=xP'b_1$. Note that $P_2$ is an ear of $H\cup (P+P_1)=H\cup P'$; likewise, $P_1$ is an ear of $H\cup (P+P_2)$. By Lemma~\ref{lem : basic prop of embmcg} \textit{(ii)}, each of $P'$, $P_1$ and $P_2$ has exactly one $2$-edge. Since $P_1$ is a subpath of $P'$, we conclude that $P$ is free of $2$-edges. Furthermore, by Lemma~\ref{lem : basic prop of embmcg} \textit{(i)}, each vertex of $P$ has degree at least three in $G$. 


